declarations.source:
@property
@abstractmethod
def configured_root_id(self) -> str:
    ...

def to_wire(self) -> dict[str, object]:
    """Schema-derived projection at a JSON boundary, not a hand-maintained mirror."""
    return FieldCodec.encode(self)

def get(self, assignment_id: str) -> WakeAssignment:
    row = WakeAssignment.one(self.session._connection, assignment_id=assignment_id)
    if row is None:
        raise IdentityConflict('unknown claim')
    return row

def accept(self, assignment: WakeAssignment) -> Applied[WakeAssignment] | AlreadyApplied[WakeAssignment]:
    assignment.require_initial_decision()
    with self.session.transaction() as db:
        rows = WakeAssignment.read(db.execute('SELECT * FROM wake_claims WHERE assignment_id=? OR (recipient_lookup=? AND wire_seq=?) LIMIT 1', (assignment.assignment_id, assignment.recipient_lookup, assignment.wire_seq)))
        row = next(iter(rows), None)
        if row is not None:
            current = row
            current.require_same_acceptance(assignment)
            return AlreadyApplied(current)
        assignment.insert(db)
        return Applied(assignment)

def recoverable_unbound_deliveries(self, recipient_lookup: str, sources: frozenset[MessageReference]) -> tuple[WakeAssignment, ...]:
    """Paused following deliveries with neither send binding nor native source."""
    from agent_comms.native_runtime_input import NativeRuntimeInput
    if not sources:
        return ()
    with self.session.read():
        db = self.session._connection
        deferred = WakeAssignment.read(db.execute(f'SELECT * FROM wake_claims claims WHERE recipient_lookup=? AND disposition={sql_literal(DeferredAssignment)} AND execution_id IS NULL AND NOT EXISTS (SELECT 1 FROM ({NativeRuntimeInput.source_membership_sql()}) sources WHERE sources.assignment_id=claims.assignment_id)', (recipient_lookup,)))
        return tuple((current for current in deferred if current.source in sources and current.lifecycle == DeferredAssignment.build(current.lifecycle.mode, None, None)))

def restore_unbound_delivery(self, captured: WakeAssignment) -> WakeAssignment:
    """Return one proved-not-sent following delivery to its declared initial state."""
    current = self.get(captured.assignment_id)
    if current != captured:
        raise StaleRevision('unbound delivery assignment changed')
    return self.transition_preengagement(current.assignment_id, current.lifecycle.mode.initial_state, expected_revision=current.revision).value

def transition_preengagement(self, assignment_id: str, disposition: type[AssignmentState], *, expected_revision: int) -> Applied[WakeAssignment]:
    with self.session.transaction() as db:
        current = self.get(assignment_id)
        if current.revision != expected_revision:
            raise StaleRevision('claim revision changed')
        lifecycle = current.lifecycle.preengagement(disposition)
        after = replace(current, updated_at_ms=self.session.now(current.updated_at_ms), revision=current.revision + 1, lifecycle=lifecycle)
        WakeAssignment.update(db, where='assignment_id=? AND revision=?', parameters=(assignment_id, expected_revision), lifecycle=after.lifecycle, updated_at_ms=after.updated_at_ms, revision=after.revision)
        return Applied(after)

def _identifier(name: str) -> str:
    if not name or not name.isascii() or (not name.replace('_', 'a').isalnum()):
        raise ValueError(f'Invalid SQL identifier: {name!r}')
    return f'"{name}"'

def _base_type(annotation: object) -> tuple[object, bool]:
    if get_origin(annotation) is Annotated:
        annotation = get_args(annotation)[0]
    if get_origin(annotation) in (Union, types.UnionType):
        members = get_args(annotation)
        if types.NoneType in members and len(members) == 2:
            return (next((member for member in members if member is not types.NoneType)), True)
    return (annotation, False)

@classmethod
@abstractmethod
def accepts(cls, annotation: object) -> bool:
    ...

@staticmethod
def _choice_constraint(column: str, values: tuple) -> str:
    choices = ', '.join(("'" + value.replace("'", "''") + "'" if isinstance(value, str) else str(int(value)) if isinstance(value, bool) else str(value) for value in values))
    return f'{_identifier(column)} IN ({choices})'

@classmethod
def family_constraints(cls, column: str, annotation: object) -> tuple[str, ...]:
    """The generated selector CHECK, also consumed by stopped DDL carries."""
    if get_origin(annotation) is Annotated:
        return ()
    declared, _ = _base_type(annotation)
    if get_origin(declared) is not type:
        return ()
    members = get_args(declared)
    if not members or not issubclass(members[0], DeclaredFamily):
        return ()
    return (cls._choice_constraint(column, members[0].names()),)

@classmethod
def constraints(cls, column: str, annotation: object=None) -> tuple[str, ...]:
    family = cls.family_constraints(column, annotation)
    if family:
        return family
    declared, _ = _base_type(annotation)
    if get_origin(declared) is Literal:
        values = get_args(declared)
    elif isinstance(declared, type) and issubclass(declared, Enum):
        if issubclass(declared, IntFlag):
            return ()
        values = tuple((member.value for member in declared))
    else:
        return ()
    return (cls._choice_constraint(column, values),)

@classmethod
def to_sql(cls, value: object) -> object:
    return FieldCodec.encode(value)

@classmethod
def from_sql(cls, value: object) -> object:
    return value

@classmethod
def for_type(cls, annotation: object) -> type[SqlStorage]:
    annotation, _ = _base_type(annotation)
    if get_origin(annotation) is Literal:
        literal_types = {type(value) for value in get_args(annotation)}
        if len(literal_types) == 1:
            annotation = next(iter(literal_types))
    for storage in cls.members_with(cls):
        if storage.accepts(annotation):
            return storage
    raise TypeError(f'Unsupported SQLite field type: {annotation!r}')

@classmethod
def accepts(cls, annotation: object) -> bool:
    return annotation is str

@classmethod
def accepts(cls, annotation: object) -> bool:
    return annotation is int

@classmethod
def accepts(cls, annotation: object) -> bool:
    return annotation is float

@classmethod
def accepts(cls, annotation: object) -> bool:
    return annotation is bool

@classmethod
def constraints(cls, column: str, annotation: object=None) -> tuple[str, ...]:
    return (*super().constraints(column, annotation), f'{_identifier(column)} IN (0, 1)')

@classmethod
def to_sql(cls, value: object) -> int:
    return int(value)

@classmethod
def from_sql(cls, value: object) -> bool:
    if type(value) is not int or value not in (0, 1):
        raise ValueError('SQLite boolean must be 0 or 1')
    return bool(value)

@classmethod
def accepts(cls, annotation: object) -> bool:
    return isinstance(annotation, type) and issubclass(annotation, Enum) and all((isinstance(member.value, str) for member in annotation))

@classmethod
def accepts(cls, annotation: object) -> bool:
    return isinstance(annotation, type) and issubclass(annotation, (IntEnum, IntFlag))

@classmethod
def accepts(cls, annotation: object) -> bool:
    args = get_args(annotation)
    return get_origin(annotation) is type and bool(args) and issubclass(args[0], DeclaredFamily)

@classmethod
def accepts(cls, annotation: object) -> bool:
    return False

@classmethod
def accepts(cls, annotation: object) -> bool:
    from dataclasses import is_dataclass
    return is_dataclass(annotation) or get_origin(annotation) in (list, tuple, dict, frozenset, Union, types.UnionType) or (isinstance(annotation, type) and issubclass(annotation, DeclaredFamily))

@classmethod
def to_sql(cls, value: object) -> str:
    return json.dumps(FieldCodec.encode(value), separators=(',', ':'), allow_nan=False)

@classmethod
def from_sql(cls, value: object) -> object:
    if type(value) is not str:
        raise ValueError('SQLite JSON must be text')
    return json.loads(value)

@property
def writable(self) -> bool:
    return self.generated is None

@property
def generated_sql(self) -> str:
    return '' if self.writable else f' GENERATED ALWAYS AS ({self.generated}) {self.generation_storage}'

def sql(self, owner: type[TypedTable], name: str, *, if_not_exists: bool=False) -> str:
    existence = 'IF NOT EXISTS ' if if_not_exists else ''
    return f"CREATE {('UNIQUE ' if self.unique else '')}INDEX {existence}{_identifier(name)} ON {_identifier(owner.declared_name)} ({owner._column_list(self.columns)})" + (f' WHERE {self.where}' if self.where else '')

def sql(self, owner: type[TypedTable]) -> str:
    if len(self.columns) != len(self.target_columns):
        raise ValueError('Foreign key column counts differ')
    return f'FOREIGN KEY ({owner._column_list(self.columns)}) REFERENCES {_identifier(self.target.declared_name)} ({self.target._column_list(self.target_columns)})' + (f' ON DELETE {self.on_delete}' if self.on_delete else '') + (' DEFERRABLE INITIALLY DEFERRED' if self.deferred else '')

@classmethod
def for_annotation(cls, annotation: object) -> SqlValue:
    return cls(annotation, SqlStorage.for_type(annotation), compile_decoder(annotation))

def read(self, cursor: sqlite3.Cursor) -> list:
    """Read a single-column projection without losing empty or nullable results."""
    try:
        if cursor.description is None or len(cursor.description) != 1:
            raise ValueError('Scalar projection requires exactly one SQLite column')
        return [self.decode(row[0]) for row in cursor]
    finally:
        cursor.close()

def encode(self, value: object) -> object:
    encoded = FieldCodec.encode(value, self.annotation)
    self.value.decode(encoded)
    return None if encoded is None else self.storage.to_sql(encoded)

@classmethod
@lru_cache(maxsize=256)
def _fields(cls) -> tuple[_Field, ...]:
    if not cls.__dataclass_params__.frozen:
        raise TypeError('SQLite row declarations must be frozen dataclasses')
    hints = get_type_hints(cls, include_extras=True)
    return tuple((_Field(name=item.name, init=item.init, annotation=hints[item.name], nullable=_base_type(hints[item.name])[1] or item.metadata.get('sql', Column()).nullable, storage=item.metadata.get('sql', Column()).storage or SqlStorage.for_type(hints[item.name]), column=item.metadata.get('sql', Column()), value=compile_decoder(hints[item.name])) for item in fields(cls)))

@classmethod
def columns(cls) -> tuple[str, ...]:
    return tuple((item.name for item in cls._fields()))

@classmethod
def _fields_named(cls, names: tuple[str, ...]) -> tuple[_Field, ...]:
    """Resolve a declared field subset, including an unfiltered query."""
    unknown = set(names).difference(cls.columns())
    if unknown:
        raise ValueError(f'Unknown fields for {cls.__name__}: {sorted(unknown)}')
    return tuple((item for item in cls._fields() if item.name in names))

@classmethod
def _positions(cls, cursor: sqlite3.Cursor, extra: tuple[str, ...]=()) -> dict[str, int]:
    if cursor.description is None:
        raise ValueError('Typed read requires a result set')
    names = tuple((item[0] for item in cursor.description))
    if len(set(names)) != len(names) or set(names) != set((*cls.columns(), *extra)):
        raise ValueError(f'Query columns do not match {cls.__name__}: {names!r}')
    return {name: index for index, name in enumerate(names)}

@classmethod
def _decode_row(cls, row: sqlite3.Row | tuple[object, ...], positions: Mapping[str, int]) -> Self:
    values = {item.name: item.decode(row[positions[item.name]]) for item in cls._fields()}
    instance = cls(**{item.name: values[item.name] for item in cls._fields() if item.init})
    for item in cls._fields():
        if not item.init:
            object.__setattr__(instance, item.name, values[item.name])
    return instance

@classmethod
def iterate(cls, cursor: sqlite3.Cursor) -> Generator[Self, None, None]:
    """Stream strictly decoded rows; close this iterator to release its query."""
    try:
        positions = cls._positions(cursor)
        for row in cursor:
            yield cls._decode_row(row, positions)
    finally:
        cursor.close()

@classmethod
def read(cls, cursor: sqlite3.Cursor) -> list[Self]:
    """Decode a complete bounded query through the same streaming boundary."""
    return list(cls.iterate(cursor))

@classmethod
def differences(cls, actual: list[SQLiteSchemaObject], expected: Mapping[str, str]) -> tuple[SQLiteSchemaDifference, ...]:
    stored = {row.name: row.sql for row in actual}
    if stored == expected:
        return ()
    return tuple((SQLiteSchemaDifference(name, stored.get(name), expected.get(name)) for name in sorted(stored.keys() | expected.keys()) if stored.get(name) != expected.get(name)))

@classmethod
def _member_declarations(cls) -> tuple[type[DeclaredFamily], ...]:
    """Enumerate the schema owner's already imported row declarations.

        Schema owners load their row modules before querying capabilities. A
        checkpoint read must not import unrelated application modules while
        holding its bus lock. External table-name decoding still uses the
        registry's complete lazy discovery through DeclaredFamily.decode.
        """
    return tuple(dict.values(cls.__registry__))

@classmethod
def references(cls) -> tuple[ForeignKey, ...]:
    return ()

@classmethod
def _column_list(cls, names: tuple[str, ...]) -> str:
    if not names:
        raise ValueError(f'Empty column list for {cls.declared_name}')
    cls._fields_named(names)
    return ', '.join(map(_identifier, names))

@classmethod
def schema_objects(cls, *, if_not_exists: bool=False) -> dict[str, str]:
    existence = 'IF NOT EXISTS ' if if_not_exists else ''
    definitions = []
    keys = tuple((item.name for item in cls._fields() if item.column.primary_key))
    auto_keys = tuple((item.name for item in cls._fields() if item.column.auto_increment))
    if auto_keys and (auto_keys != keys or len(keys) != 1 or cls.without_rowid):
        raise TypeError('AUTOINCREMENT requires one rowid primary key')
    for item in cls._fields():
        column = item.column
        sql = f'{_identifier(item.name)} {item.storage.sql_type}'
        if column.auto_increment:
            sql += ' PRIMARY KEY AUTOINCREMENT'
        sql += column.generated_sql
        if not item.nullable or column.primary_key:
            sql += ' NOT NULL'
        if column.unique:
            sql += ' UNIQUE'
        if column.references is not None:
            target, name = column.references
            target._column_list((name,))
            sql += f' REFERENCES {_identifier(target.declared_name)} ({_identifier(name)})'
        for constraint in item.storage.constraints(item.name, item.annotation):
            sql += f' CHECK ({constraint})'
        if column.check:
            sql += f' CHECK ({column.check})'
        definitions.append(sql)
    if keys and (not auto_keys):
        definitions.append(f'PRIMARY KEY ({cls._column_list(keys)})')
    elif cls.without_rowid:
        raise TypeError('WITHOUT ROWID requires a declared primary key')
    definitions.extend((f'UNIQUE ({cls._column_list(group)})' for group in cls.unique))
    definitions.extend((f'CHECK ({check})' for check in cls.checks))
    definitions.extend((reference.sql(cls) for reference in cls.references()))
    table = _identifier(cls.declared_name)
    statements = {cls.declared_name: f"CREATE TABLE {existence}{table} ({', '.join(definitions)}) STRICT" + (', WITHOUT ROWID' if cls.without_rowid else '')}
    indexes = cls.indexes + tuple((Index((item.name,)) for item in cls._fields() if item.column.index))
    for ordinal, index in enumerate(indexes):
        index_name = f'{cls.declared_name}_{ordinal}_idx'
        statements[index_name] = index.sql(cls, index_name, if_not_exists=if_not_exists)
    statements.update(cls.triggers(if_not_exists=if_not_exists))
    return statements

@classmethod
def trigger_bodies(cls) -> dict[str, str]:
    """Named trigger suffixes, including their leading SQL whitespace."""
    return {}

@classmethod
def triggers(cls, *, if_not_exists: bool=False) -> dict[str, str]:
    existence = 'IF NOT EXISTS ' if if_not_exists else ''
    return {name: f'CREATE TRIGGER {existence}{name}{body}' for name, body in cls.trigger_bodies().items()}

@classmethod
def ddl(cls, *, if_not_exists: bool=False) -> tuple[str, ...]:
    return tuple(cls.schema_objects(if_not_exists=if_not_exists).values())

@classmethod
def create(cls, db: sqlite3.Connection, *, if_not_exists: bool=False) -> None:
    """Create the declared schema; SQLite owns concurrent existence checks."""
    for statement in cls.ddl(if_not_exists=if_not_exists):
        db.execute(statement)

@classmethod
def _condition(cls, where: str, parameters: tuple, key: dict[str, object]) -> tuple[str, tuple]:
    """Compile declared key values once for reads and keyed removals."""
    selected = cls._fields_named(tuple(key))
    if selected:
        where = '(' + where + ') AND ' + ' AND '.join((f'{_identifier(item.name)} IS ?' for item in selected))
        parameters = (*parameters, *(item.encode(key[item.name]) for item in selected))
    return (where, parameters)

@classmethod
def _query(cls, db: sqlite3.Connection, where: str, parameters: tuple, order_by: tuple[str, ...], descending: bool, key: dict[str, object]) -> sqlite3.Cursor:
    where, parameters = cls._condition(where, parameters, key)
    cls._fields_named(order_by)
    direction = ' DESC' if descending else ''
    return db.execute(f'SELECT {cls._column_list(cls.columns())} FROM {_identifier(cls.declared_name)} WHERE {where}' + (' ORDER BY ' + ', '.join((_identifier(name) + direction for name in order_by)) if order_by else ''), parameters)

@classmethod
def select(cls, db: sqlite3.Connection, *, where: str='1', parameters: tuple=(), order_by: tuple[str, ...]=(), descending: bool=False, **key: object) -> list[Self]:
    return cls.read(cls._query(db, where, parameters, order_by, descending, key))

@classmethod
def stream(cls, db: sqlite3.Connection, *, where: str='1', parameters: tuple=(), order_by: tuple[str, ...]=(), descending: bool=False, **key: object) -> Generator[Self, None, None]:
    """Rows decoded as the caller consumes them; close it to release the query."""
    return cls.iterate(cls._query(db, where, parameters, order_by, descending, key))

@classmethod
def one(cls, db: sqlite3.Connection, **key: object) -> Self | None:
    rows = cls.select(db, **key)
    if len(rows) > 1:
        raise ValueError(f'Expected one {cls.declared_name} for {tuple(key)}')
    return next(iter(rows), None)

@classmethod
def present(cls, db: sqlite3.Connection) -> bool:
    return SqlValue.for_annotation(bool).read(db.execute("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name=?)", (cls.declared_name,)))[0]

@classmethod
def exists(cls, db: sqlite3.Connection, *, where: str='1', parameters: tuple=()) -> bool:
    return SqlValue.for_annotation(bool).read(db.execute(f'SELECT EXISTS(SELECT 1 FROM {_identifier(cls.declared_name)} WHERE {where})', parameters))[0]

@classmethod
def column_values(cls, db: sqlite3.Connection, name: str, *, where: str='1', parameters: tuple=()) -> list:
    selected, = cls._fields_named((name,))
    return selected.read(db.execute(f'SELECT {_identifier(selected.name)} FROM {_identifier(cls.declared_name)} WHERE {where}', parameters))

@classmethod
def _writable_fields(cls, columns: tuple[str, ...] | None=None) -> tuple[_Field, ...]:
    if columns is None:
        return tuple((item for item in cls._fields() if item.column.writable))
    selected = cls._fields_named(columns)
    if any((not item.column.writable for item in selected)):
        raise ValueError('Generated columns cannot be written')
    return selected

@classmethod
def insertion_statement(cls, columns: tuple[str, ...]=()) -> str:
    writable = cls._writable_fields(columns or None)
    return f"INSERT INTO {_identifier(cls.declared_name)} ({cls._column_list(tuple((item.name for item in writable)))}) VALUES ({', '.join(('?' for _ in writable))})"

@classmethod
def insert_values(cls, db: sqlite3.Connection, **values: object) -> sqlite3.Cursor:
    writable = cls._writable_fields(tuple(values) or None)
    return db.execute(cls.insertion_statement(tuple((item.name for item in writable))), tuple((item.encode(values[item.name]) for item in writable)))

@classmethod
def delete(cls, db: sqlite3.Connection, *, where: str='1', parameters: tuple=(), **key: object) -> sqlite3.Cursor:
    where, parameters = cls._condition(where, parameters, key)
    return db.execute(f'DELETE FROM {_identifier(cls.declared_name)} WHERE {where}', parameters)

def _insertion(self) -> tuple[str, tuple]:
    writable = self._writable_fields()
    return (self.insertion_statement(), tuple((item.encode(getattr(self, item.name)) for item in writable)))

def insert_if_absent(self, db: sqlite3.Connection) -> sqlite3.Cursor:
    statement, values = self._insertion()
    return db.execute(statement + ' ON CONFLICT DO NOTHING', values)

@classmethod
def update(cls, db: sqlite3.Connection, *, where: str, parameters: tuple=(), **changes: object) -> sqlite3.Cursor:
    selected = cls._writable_fields(tuple(changes))
    if not selected:
        raise ValueError(f'Update requires fields for {cls.declared_name}')
    return db.execute(f'UPDATE {_identifier(cls.declared_name)} SET ' + ', '.join((f'{_identifier(item.name)}=?' for item in selected)) + f' WHERE {where}', tuple((item.encode(changes[item.name]) for item in selected)) + parameters)

@property
def path(self) -> Path:
    return self.root / self.filename

@classmethod
def declared_schema(cls) -> dict[str, str]:
    return {name: sql for row in cls.rows for name, sql in row.schema_objects().items()}

@staticmethod
def _schema(connection: sqlite3.Connection) -> list[SQLiteSchemaObject]:
    return SQLiteSchemaObject.read(connection.execute("SELECT name,sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%'"))

def retire(*error):
    with _store_lock(self.path):
        return resource.__exit__(*error)

def _open_writer(self) -> sqlite3.Connection:
    """Attach and install an absent store under the connection boundary."""
    from .coordination_database import CoordinationStore
    try:
        descriptor = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_RDWR, 384)
    except FileExistsError:
        pass
    else:
        os.close(descriptor)
    connection = CoordinationStore.writer(self.path, isolation_level=None)
    try:
        connection.execute(f'PRAGMA synchronous={self.synchronous}')
        if not self._schema(connection):
            connection.execute('BEGIN IMMEDIATE')
            if not self._schema(connection):
                for row in self.rows:
                    row.create(connection)
            connection.execute('COMMIT')
        if SQLiteJournalMode.read(connection.execute('PRAGMA journal_mode=WAL')) != [SQLiteJournalMode('wal')]:
            raise RelationViolationError(f'{self.filename} requires WAL')
        return connection
    except BaseException:
        connection.close()
        raise

def require_schema(self, actual: list[SQLiteSchemaObject]) -> None:
    if SQLiteSchemaObject.differences(actual, self.declared_schema()):
        raise RelationViolationError(f'{self.filename} differs from its declaration')

@contextmanager
def writing(self) -> Iterator[sqlite3.Connection]:
    with self._attached(lambda: closing(self._open_writer())) as connection:
        try:
            connection.execute('BEGIN IMMEDIATE')
            self.require_schema(self._schema(connection))
            yield connection
            connection.execute('COMMIT')
        except BaseException:
            if connection.in_transaction:
                connection.execute('ROLLBACK')
            raise

@abstractmethod
def settle(self, store, db, current: WakeAssignment) -> None:
    ...

@abstractmethod
def settle(self, participant, stage, admission, context) -> tuple[WakeAssignment, ...]:
    ...

@handles(pi.Response)
def accepted(self, event):
    if event.id == 'native-prompt' and event.success and self.current.starting:
        self.advance(PromptAcceptedAttempt)

@classmethod
def capture(cls, snapshot: RegistrySnapshot, catalog: CatalogDocument, reads: ReadLedger, document: ReadDocument, viewer: str | None) -> DisplaySelection:
    canonical = snapshot.canonical_name(viewer) if viewer is not None else None
    seen = reads.seen_sequences(viewer, snapshot, document=document) if viewer is not None else frozenset()
    return cls(snapshot, catalog, canonical, seen, document)

@classmethod
def capture(cls, thread: Thread, snapshot: RegistrySnapshot, activity: ObservedActivity, runtime: AgentRuntimeInfo | None, waits: dict[str, GoalWait]) -> ThreadView:
    """Roster and individual readers join the same captured authorities."""
    return cls(thread, snapshot.statuses[thread.name], activity, runtime, snapshot.seen_at(thread.name), GoalWaits.execution(thread.goal, waits, snapshot), snapshot.owner_binding(thread.name))

async def pass_on_unread(self, turns: TurnRunner) -> None:
    """Inputs the ended turn never read start the next turn or are refused, never replayed."""
    while not self.inbox.empty():
        for carried in self.inbox.get_nowait().carried_inputs:
            if await self.pass_on(turns, carried.value):
                return

def bind(self, sessions: SessionLifecycle, inputs: InputDrain) -> None:
    self.sessions = sessions
    self.inputs = inputs

def write(self, record: Checkpoint) -> None:
    payload = json.dumps(self._encode(record))
    with _store_lock(self.path):
        try:
            stream = self.source_path.open('rb')
        except FileNotFoundError:
            return
        with stream:
            current = FileRevision.from_stat(os.fstat(stream.fileno()))
            if not record.accepts(current, stream):
                return
            saved = self._read_unlocked()
            if saved is not None and saved.accepts(current, stream) and (saved.offset > record.offset):
                return
        self._write_unlocked(payload)

def capture(self, prepared: Checkpoint | None, stream: BinaryIO | None, revision: FileRevision | None) -> Checkpoint | None:
    if prepared is None or stream is None or revision is None:
        return None
    self._held = prepared if prepared.accepts(revision, stream) else None
    return self._held

def write(conn: sqlite3.Connection) -> Generation:
    goal = Generation.read_in(conn, reservation.goal_id)
    attempt = AttemptRecord.read_in(conn, reservation.attempt_id)
    if goal != Generation(reservation.goal_id, reservation.generation, ReservedGeneration(), reservation.attempt_id) or (attempt is None or attempt.reservation != reservation or (not attempt.phase.may_become(FailedAttempt()))):
        raise StaleAttemptError('Late failure cannot modify this goal generation.')
    attempt.advance(conn, FailedAttempt(), resolution=diagnostic)
    if observation is not None and attempt.phase.launched:
        record_observation(conn, reservation, observation)
    return goal.advance(conn, Generation(reservation.goal_id, reservation.generation, BlockedGeneration(), reservation.attempt_id))

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    attempt = reservation.require_current(conn, ClaimedAttempt())
    attempt.advance(conn, SucceededAttempt(), progress_witness=progress_witness)
    current = Generation(reservation.goal_id, reservation.generation, ReservedGeneration(), reservation.attempt_id)
    return current.advance(conn, Generation(reservation.goal_id, reservation.generation + 1, ReadyGeneration(), None), digest=digest)

def write(conn: sqlite3.Connection) -> Generation:
    attempt = reservation.require_current(conn, ClaimedAttempt())
    attempt.advance(conn, SucceededAttempt(), progress_witness=witness)
    current = Generation(reservation.goal_id, reservation.generation, ReservedGeneration(), reservation.attempt_id)
    return current.advance(conn, Generation(reservation.goal_id, reservation.generation, CompletedGeneration(), reservation.attempt_id))

def write(conn: sqlite3.Connection) -> str:
    reservation.require_current(conn, ClaimedAttempt())
    row = GoalProviderUsage.one(conn, attempt_id=reservation.attempt_id, response_id=response_id)
    if row is not None:
        if row.usage_json != raw:
            raise ValueError('Provider response ID has different usage.')
    else:
        GoalProviderUsage(reservation.attempt_id, response_id, raw).insert(conn)
    return raw

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, ReadyGeneration(), None):
        raise ReservationConflictError('Only an unreserved READY generation can be recovered.')
    return current.advance(conn, current, digest=digest)

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    if Generation.one(conn, goal_id=goal_id) is not None:
        raise ReservationConflictError('Goal ID already has a ledger.')
    row = Generation(goal_id, 1, ReadyGeneration(), None, ready_digest=digest)
    row.insert(conn)
    return row

def write(conn: sqlite3.Connection) -> Reservation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, ReadyGeneration(), None):
        raise ReservationConflictError('Goal generation is not ready or already reserved.')
    if not hmac.compare_digest(current.ready_digest, digest):
        raise UnresolvedAttemptError('Ready grant is stale or was never acknowledged.')
    AttemptRecord(attempt, ReservedAttempt(), None, None).insert(conn)
    current.advance(conn, Generation(goal_id, expected_generation, ReservedGeneration(), attempt.attempt_id))
    return attempt

def write(conn: sqlite3.Connection) -> LaunchPermit:
    current = reservation.require_current(conn, ReservedAttempt())
    current.advance(conn, ClaimedAttempt())
    return LaunchPermit(reservation)

def write(conn: sqlite3.Connection) -> Generation:
    goal = Generation.read_in(conn, goal_id)
    attempt = AttemptRecord.read_in(conn, attempt_id)
    if goal != Generation(goal_id, expected_generation, ReservedGeneration(), attempt_id) or (attempt is None or attempt.reservation.identity != GoalAttemptIdentity(goal_id, expected_generation, attempt_id) or (not attempt.phase.may_become(FailedAttempt()))):
        raise StaleAttemptError('Attempt changed before human abandonment decision.')
    GoalHumanDecision(goal_id, user_decision_id, expected_generation).claim(conn)
    attempt.advance(conn, FailedAttempt(), resolution=user_decision_id)
    return goal.advance(conn, Generation(goal_id, expected_generation, BlockedGeneration(), attempt_id))

def resume(self, goal_id: str, expected_generation: int) -> Generation:
    """Ordinary same-ID resume never resolves a reserved or blocked attempt."""
    current = self.snapshot(goal_id)
    if current is None or current.number != expected_generation:
        raise StaleAttemptError('Goal generation changed before resume.')
    if not current.lifecycle.ready or current.attempt_id is not None:
        raise UnresolvedAttemptError('Explicit attempt resolution is required before resume.')
    self.ready_grant(goal_id, expected_generation)
    return current

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, ReadyGeneration(), None):
        raise UnresolvedAttemptError('Goal is not ready; an attempt may already be unresolved.')
    GoalHumanDecision(goal_id, user_decision_id, expected_generation).claim(conn)
    return current.advance(conn, Generation(goal_id, expected_generation + 1, ReadyGeneration(), None), digest=digest)

def write(conn: sqlite3.Connection, digest: str) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current != Generation(goal_id, expected_generation, BlockedGeneration(), attempt_id):
        raise UnresolvedAttemptError('Blocked attempt changed or is not resolved.')
    attempt = AttemptRecord.read_in(conn, attempt_id)
    if attempt is None or attempt.reservation.identity != GoalAttemptIdentity(goal_id, expected_generation, attempt_id) or (not isinstance(attempt.phase, FailedAttempt)):
        raise UnresolvedAttemptError('Only a blocked, recorded failure may be retried explicitly.')
    GoalHumanDecision(goal_id, user_decision_id, expected_generation).claim(conn)
    attempt.advance(conn, ResolvedAttempt(), resolution=user_decision_id)
    return current.advance(conn, Generation(goal_id, expected_generation + 1, ReadyGeneration(), None), digest=digest)

def write(conn: sqlite3.Connection) -> Generation:
    current = Generation.read_in(conn, goal_id)
    if current is None or current.number != expected_generation or current.attempt_id != attempt_id:
        raise StaleAttemptError('Goal generation or attempt changed before retirement.')
    attempt = AttemptRecord.read_in(conn, attempt_id) if attempt_id is not None else None
    if attempt_id is not None and (attempt is None or attempt.reservation.identity != GoalAttemptIdentity(goal_id, expected_generation, attempt_id)):
        raise StaleAttemptError('Unresolved goal has no matching attempt to retire.')
    if not current.lifecycle.permits_retirement(attempt.phase if attempt else None):
        raise StaleAttemptError('Goal or attempt is no longer eligible for retirement.')
    if attempt is not None:
        attempt.advance(conn, ResolvedAttempt(), resolution='goal cleared')
    return current.advance(conn, Generation(goal_id, expected_generation, CancelledGeneration(), attempt_id))

