def reserve(self, dispositions: InputDispositions, owner: Thread, turn: TurnId, admission: int, *, custody: ExitStack) -> OriginalTurnInput:
    """Every original uses the same durable input authority before native preparation.

        ACP and bus inputs already own ingress keys. A scheduled original has no
        external ingress; its admitted turn supplies identity, never replay authority.
        """
    if self.keys:
        return self
    batch = dispositions.reserve_turn(owner.name, turn, admission, self.prompt, custody=custody)
    return replace(self, batch=batch)

async def next_event(self) -> pi.PiEvent:
    try:
        while True:
            refused, self.rejected_commands = (self.rejected_commands, [])
            self.rejected_signal.clear()
            for command in refused:
                await self.following.retired(command)
            raw = await self.watchdog.read(self)
            if not self.rejected_commands:
                break
        event = PiRpcChannel.decode_record(raw, strict=True) if raw else None
    except (UnicodeError, ValueError, TypeError) as error:
        raise NativePiUnavailable(f'Native Pi RPC record is invalid or incomplete; {type(error).__name__}: {error}') from error
    if event is None:
        await self.native.shutdown(graceful=True)
        stderr = await self.native.stderr_task
        raise NativePiUnavailable(f"Native Pi RPC record is incomplete; native exit={self.native.proc.returncode}; stderr={stderr or '(empty)'}")
    return event

async def send(self, command: commands.PiCommand) -> None:
    payload = self.native.reader.encode(command)
    if self.maintenance_root is not None:
        try:
            async with MaintenanceBarrier(self.maintenance_root / 'registry.json').admit_ingress_async():
                self.write(command, payload)
        except RelationViolationError as error:
            raise NativePiUnavailable('Maintenance closed before Pi capability preflight') from error
    else:
        self.write(command, payload)
    wait = self.watchdog.wait_for(self)
    with wait.charge(self.watchdog.clock):
        await asyncio.wait_for(self.native.proc.stdin.drain(), timeout=wait.timeout())

def write(self, command: commands.PiCommand, payload: bytes) -> None:
    if command is self.command:
        self.grant_prompt()
    self.native.proc.stdin.write(payload)

def commit(self, database: sqlite3.Connection) -> None:
    current = ReplyIndex.one(database, source=self.after.source) or ReplyIndex(source=self.after.source)
    if current != self.before:
        return
    if not self.before.continues(self.after.revision):
        database.execute(f'DELETE FROM {TranscriptReply.declared_name} WHERE source=?', (self.after.source,))
    for reply in self.replies:
        reply.insert(database)
    self.after.upsert(database)

def commit(self, database: sqlite3.Connection, wanted: Collection[str]) -> str | None:
    if self.future.cancelled():
        return None
    batch = self.future.result()
    try:
        with database:
            database.execute('BEGIN IMMEDIATE')
            for update in batch.updates:
                source = update.after.source
                if source not in self.reads or source not in wanted:
                    continue
                revision = FileRevision.capture(Path(source))
                expected = self.reads[source][1]
                if revision is not None and expected.holds_cut(revision, expected.size):
                    update.commit(database)
    except sqlite3.OperationalError as error:
        CoordinationReadUnavailable.raise_from(error)
    return batch.last_source

