@classmethod
def for_deliveries(cls, originals: Iterable[CommittedDelivery], records: Iterable[NotificationAssignment]) -> Iterator[tuple[CommittedDelivery, tuple[NotificationSource, ...]]]:
    """Match one acquired window by its original source and recipient identities."""
    by_recipient = {}
    for record in records:
        key = (record.assignment.source, record.assignment.recipient_lookup)
        by_recipient.setdefault(key, []).append(record)
    for original in originals:
        reference = original.message.reference
        sources = []
        for recipient, decision in zip(original.audience.recipients, original.decisions, strict=True):
            matching = by_recipient.get((reference, recipient.recipient_lookup), ())
            if len(matching) > 1:
                raise ValueError('Original notification recipient has multiple handling receipts')
            sources.append(matching[0] if matching else UnrecordedNotificationSource(recipient, decision))
        yield (original, tuple(sources))

@classmethod
def database_path(cls, root: Path) -> Path:
    return root / 'coordination.sqlite3'

@classmethod
def source_paths(cls, root: Path) -> tuple[Path, ...]:
    """SQLite and the certified bus own assignment and delivered-response changes."""
    database = cls.database_path(root)
    bus = root / 'bus.jsonl'
    return (database, database.with_name(database.name + '-wal'), bus, bus.with_name('bus_meta.json'), bus.with_name('private_bus_checkpoint.sqlite3'))

@classmethod
def _recorded_conversation_responses(cls, root: Path, sources: tuple[CommittedDelivery, ...], rows: tuple[NotificationAssignment, ...]) -> tuple[NotificationAssignment, ...]:
    eligible = tuple((row for row in rows if row.assignment.lifecycle.records_conversation_response))
    if not eligible:
        return rows
    from .wire_log import WireLog
    originals = {original.message.reference: original for original in sources}
    with WireLog(root / 'bus.jsonl').certified_read() as source:
        captured = source.replies(tuple({row.assignment.source for row in eligible}))
    replies: dict[MessageReference, list[CommittedDelivery]] = {}
    for reply in captured:
        for answered in reply.message.answers:
            replies.setdefault(answered, []).append(reply)
    resolved = []
    for row in rows:
        if row.assignment.lifecycle.records_conversation_response:
            response = row.assignment.lifecycle.recorded_response(originals[row.assignment.source], replies.get(row.assignment.source, ()), row.assignment.recipient_lookup)
            if response is not None:
                row = replace(row, activity=row.activity.recorded_response(response))
        resolved.append(row)
    return tuple(resolved)

@classmethod
def capture(cls, connection: sqlite3.Connection, sources: Sequence[CommittedDelivery]) -> NotificationAssignmentRead:
    """Capture detached assignment evidence for one bounded window of originals
        from the caller's SQLite snapshot."""
    from .presentation import MessageNotification
    sources = tuple(sources)
    if len(sources) > MessageNotification.window_limit:
        raise ValueError('Notification reads require a bounded visible message window')
    if not sources:
        return NotificationAssignmentRead((), ())
    from .coordination_tables.executions import CurrentExecutions
    from .native_input_record import TriageNativeExecution
    from .native_runtime_input import NativeRuntimeInput
    if SQLiteUserVersion.read(connection.execute('PRAGMA user_version')) != [SQLiteUserVersion(COORDINATION_SCHEMA_VERSION)]:
        raise ValueError('Channel notification status has an unsupported schema')
    columns = ','.join((f'w.{name}' for name in WakeAssignment.columns()))
    triage_stage = sql_literal(TriageNativeExecution)
    rows = WakeAssignment.joined(connection.execute(f"WITH w AS MATERIALIZED (SELECT * FROM {WakeAssignment.declared_name} WHERE wire_seq IN ({','.join(('?' for _ in sources))})), member AS MATERIALIZED (SELECT m.input_id,m.assignment_id,m.ordinal FROM ({NativeRuntimeInput.source_membership_sql()}) m WHERE m.assignment_id IN (SELECT assignment_id FROM w)) SELECT {columns}, EXISTS (SELECT 1 FROM {NativeRuntimeInput.declared_name} n JOIN member ON member.input_id=n.input_id WHERE member.assignment_id=w.assignment_id AND n.stage={triage_stage} AND n.session_entry_id IS NULL) AS triage_inflight, pointer.execution_id AS current_execution_id, (SELECT n.committed_at_ms FROM {NativeRuntimeInput.declared_name} n JOIN member ON member.input_id=n.input_id WHERE member.assignment_id=w.assignment_id AND n.session_entry_id IS NOT NULL ORDER BY CASE n.stage WHEN {triage_stage} THEN 0 ELSE 1 END,member.ordinal,n.input_id LIMIT 1) AS context_committed_at_ms, p.seq AS response_seq, p.message_id AS response_message_id, p.received_at_ms AS response_received_at_ms FROM w LEFT JOIN {CurrentExecutions.declared_name} pointer ON pointer.owner_lookup=w.recipient_lookup LEFT JOIN {PublicationReceipts.declared_name} p ON p.execution_id=w.execution_id AND p.exact_target=w.exact_target ORDER BY w.wire_seq DESC,w.recipient", tuple((source.message.seq for source in sources))), AssignmentActivityEvidence)
    return NotificationAssignmentRead(sources, tuple(rows))

@classmethod
def read(cls, root: Path, sources: Sequence[CommittedDelivery]) -> NotificationAssignmentRead:
    """Capture assignment evidence through the single observing connection owner."""
    from .coordination_database import CoordinationStore
    database = cls.database_path(root)
    failure = CoordinationStore.observation_failure(database)
    if failure == 'missing':
        return NotificationAssignmentRead(tuple(sources), ())
    if failure:
        raise ValueError(f'Channel notification status unavailable: {failure}')
    with CoordinationStore.observing(database) as connection:
        return cls.capture(connection, sources)

@property
