def verify(self, store: Coordination, owner: ParticipantOwner, input_id: str, token_digest: str, context: NativeContextProof, *, wire_root_id: str, prompt: str) -> None:
    with NativeEntry.open_input_evidence(context.session_file) as evidence:
        if not context.corroborates_input(input_id, evidence=evidence):
            raise IdentityConflict('Pi live assembled context differs from its reserved input proof')
        with self.bound_prompt(store, input_id, owner, wire_root_id, prompt, blocking=True) as binding:
            if not expected_prompt_matches_journal(context.session_file, binding, evidence=evidence):
                raise IdentityConflict('live native input lacks exact bound source prompt equality')
            with store.session.read():
                original = self.pending_input(store, input_id, owner, token_digest)
                original.require_session_identity().require_context(context)

def require_claim(self, store: Coordination) -> None:
    for captured in self.assignments:
        current = store.assignments.get(captured.assignment_id)
        try:
            NativeClaimCheck(captured=captured, current=current).require_valid()
        except ReservationViolationError as error:
            raise StaleFence(f'selected claim identity changed before native send: {error}') from error
        self.require_phase(store, current)

def require_reservation(self, db: sqlite3.Connection, input_id: str, owner: ParticipantOwner, token_digest: str) -> NativeRuntimeInput:
    reserved = NativeRuntimeInput.one(db, input_id=input_id)
    if reserved is None:
        raise StaleFence('native reservation missing before send')
    self.require_sources(db, input_id)
    try:
        NativeReservationCheck(row=reserved, stage=self, owner=owner.coordinator_identity(self.recipient_lookup), token_digest=token_digest).require_valid()
    except ReservationViolationError as error:
        raise StaleFence(f'native reservation changed before send: {error}') from error
    return reserved

def require_sources(self, db, input_id) -> None:
    if self.execution.source_assignment_ids(db, input_id) != tuple((row.assignment_id for row in self.assignments)):
        raise IdentityConflict('Native input changed its original source membership')

@contextmanager
def bound_prompt(self, store: Coordination, input_id: str, owner: ParticipantOwner, wire_root_id: str, prompt: str, *, blocking: bool=False) -> Iterator[PromptBinding]:
    with expected_prompt_binding(store, input_id, blocking=blocking) as binding:
        self.require_bound_prompt(binding, owner, wire_root_id, prompt)
        yield binding

def require_bound_prompt(self, binding: PromptBinding | None, owner: ParticipantOwner, wire_root_id: str, prompt: str) -> None:
    if binding is None:
        raise IdentityConflict('native send has no durable prompt binding')
    try:
        NativeBindingCheck(row=binding, stage=self, owner=owner.coordinator_identity(self.recipient_lookup), wire_root_id=wire_root_id, prompt_digest=TextDigest(native_request_digest(prompt))).require_valid()
    except ReservationViolationError as error:
        raise IdentityConflict(f'native send differs from its durable prompt binding: {error}') from error

def fail_claims(self, store: Coordination, db: sqlite3.Connection) -> tuple[WakeAssignment, ...]:
    """Move this triage's deferred claims to Failed inside the caller's transaction."""
    for captured in self.assignments:
        current = store.assignments.get(captured.assignment_id)
        if current.lifecycle != DeferredAssignment.build(current.lifecycle.mode, None, None):
            raise StaleFence('failed triage claim is no longer deferred')
        updated = WakeAssignment.update(db, where='assignment_id=? AND revision=?', parameters=(current.assignment_id, current.revision), lifecycle=current.lifecycle.preengagement(FailedAssignment), revision=current.revision + 1, updated_at_ms=store.session.now(current.updated_at_ms))
        if updated.rowcount != 1:
            raise StaleFence('failed triage lost an original batch claim')
    return tuple((store.assignments.get(captured.assignment_id) for captured in self.assignments))

@property
def execution(self) -> TriageNativeExecution:
    return TriageNativeExecution()

def reserve_claim(self, store: Coordination, db: sqlite3.Connection) -> None:
    for captured in self.assignments:
        current = store.assignments.get(captured.assignment_id)
        if current != captured:
            raise IdentityConflict('triage claim changed before native batch reservation')
        reserved = current.lifecycle.reserve_triage()
        if SqlValue.for_annotation(int).read(db.execute(f'SELECT 1 FROM ({self.execution.source_membership_sql()}) members WHERE members.assignment_id=? LIMIT 1', (captured.assignment_id,))):
            raise IdentityConflict('triage source was previously reserved; no retry')
        update = WakeAssignment.update(db, where='assignment_id=? AND revision=? AND disposition=?', parameters=(current.assignment_id, current.revision, current.lifecycle.declared_name), lifecycle=reserved, revision=current.revision + 1, updated_at_ms=store.session.now(current.updated_at_ms))
        if update.rowcount != 1:
            raise IdentityConflict('triage batch reservation lost an original claim CAS')

def commit(self, store: Coordination, owner: ParticipantOwner, input_id: str, token_digest: str, context: NativeContextProof, decision: SelectedTriage) -> tuple[WakeAssignment, ...]:
    with store.session.transaction() as db:
        row = self.pending_input(store, input_id, owner, token_digest)
        self.require_claim(store)
        row.commit_context(db, context, verdict=type(decision))
        for captured in self.assignments:
            decision.settle(store, db, store.assignments.get(captured.assignment_id))
        return tuple((store.assignments.get(captured.assignment_id) for captured in self.assignments))

def require_phase(self, store: Coordination, current: WakeAssignment) -> None:
    if current.lifecycle != DeferredAssignment.build(current.lifecycle.mode, None, None) or current.revision != next((row.revision for row in self.assignments if row.assignment_id == current.assignment_id)) + 1:
        raise StaleFence('triage claim changed before native send')

@property
def fence(self):
    return self.progress.fence

@property
def execution(self) -> FullNativeExecution:
    return FullNativeExecution(self.fence.execution_id, self.fence.attempt_ordinal)

def reserve_claim(self, store: Coordination, db: sqlite3.Connection) -> None:
    snapshot, _ = store.attempts.require_fence(self.fence)
    self.require_claim(store)
    if snapshot.pointer_revision < 1 or self.assignments != snapshot.assignments:
        raise StaleFence('full input cannot bind to the current attempt')
    if NativeRuntimeInput.select(db, where='execution_id=? AND attempt_ordinal=?', parameters=(self.execution.execution_id, self.execution.attempt_ordinal)):
        raise IdentityConflict('this execution attempt already has a native input')

def require_phase(self, store: Coordination, current: WakeAssignment) -> None:
    snapshot, attempt = store.attempts.require_fence(self.fence)
    if not isinstance(current.lifecycle, snapshot.execution.lifecycle.assignment_state()) or not snapshot.execution.lifecycle.active or (not attempt.lifecycle.starting) or attempt.lifecycle.backend_done or attempt.lifecycle.process_dead:
        raise StaleFence('full execution is not running before native send')

def create(self, execution_id: str, origin: ExecutionOrigin, owner_lookup: str, owner_thread: str, max_attempts: int, *, sources: tuple[SelectedSource, ...]=()) -> Applied[RecoverySnapshot] | AlreadyApplied[RecoverySnapshot]:
    with self.session.transaction() as db:
        assignments = tuple((source.assignment for source in sources))
        return self._create(db, execution_id, origin, owner_lookup, owner_thread, max_attempts, sources, assignments)

def create_after_triage(self, execution_id: str, origin: ExecutionOrigin, owner_lookup: str, owner_thread: str, max_attempts: int, *, sources: tuple[SelectedSource, ...], settled: tuple[WakeAssignment, ...]) -> Applied[RecoverySnapshot] | AlreadyApplied[RecoverySnapshot]:
    """Engage exactly the rows witnessed by the original triage proof commit."""
    with self.session.transaction() as db:
        assignments = tuple((source.assignment for source in sources))
        if assignments != settled:
            raise StaleRevision('original claims changed after proved native settlement')
        return self._create(db, execution_id, origin, owner_lookup, owner_thread, max_attempts, sources, assignments)

def _create(self, db, execution_id, origin, owner_lookup, owner_thread, max_attempts, sources, assignments):
    """The single creation algorithm, under its caller's owning transaction."""
    origin = ExecutionOrigin(origin)
    for source in sources:
        if source.store is not self.assignments:
            raise IdentityConflict('execution source belongs to another assignment store')
    assignment_ids = tuple((source.assignment_id for source in sources))
    if origin is ExecutionOrigin.WIRE and (not sources):
        raise IdentityConflict('wire execution requires ordered original sources')
    if origin is not ExecutionOrigin.WIRE and sources:
        raise IdentityConflict('claimless execution cannot bind claims')
    row = ExecutionRecord.one(self.session._connection, execution_id=execution_id)
    if row is not None:
        snapshot = self.snapshots.get(execution_id)
        e = snapshot.execution
        if (e.origin, e.owner_lookup, e.owner_thread, e.max_attempts, tuple(sorted((row.exact_target for row in snapshot.obligations))), tuple((link.assignment_id for link in snapshot.links))) != (origin, owner_lookup, owner_thread, max_attempts, tuple(sorted({source.delivery.message.exact_reply_target for source in sources})), assignment_ids):
            raise IdentityConflict('execution identity conflicts')
        return AlreadyApplied(snapshot)
    participant = self.participants.get(owner_lookup)
    if not participant.committed or participant.owner_thread != owner_thread:
        raise IdentityConflict('execution requires committed current owner')
    if not isinstance(max_attempts, int) or max_attempts <= 0:
        raise ValueError('max_attempts must be positive')
    if len(set(assignment_ids)) != len(assignment_ids):
        raise IdentityConflict('duplicate claim membership')
    now = self.session.now()
    ExecutionRecord(execution_id=execution_id, origin=origin, lifecycle=QueuedExecution(), owner_thread=owner_thread, owner_lookup=owner_lookup, revision=1, max_attempts=max_attempts, reason_code=None, created_at_ms=now, updated_at_ms=now).insert(db)
    routes = {}
    for ordinal, (source, assignment) in enumerate(zip(sources, assignments, strict=True)):
        assignment_id = source.assignment_id
        exact_target = source.delivery.message.exact_reply_target
        routes.setdefault(exact_target, None)
        if assignment.recipient_lookup != owner_lookup or assignment.lifecycle.execution_id is not None or EngagedAssignment not in assignment.lifecycle.successors():
            raise IdentityConflict('claim cannot engage this execution')
        decision = EngagedAssignment.build(assignment.lifecycle.mode, execution_id, exact_target)
        updated = WakeAssignment.update(db, where='assignment_id=? AND revision=?', parameters=(assignment_id, assignment.revision), lifecycle=decision, revision=assignment.revision + 1, updated_at_ms=self.session.now(assignment.updated_at_ms))
        if updated.rowcount != 1:
            raise StaleRevision('original claim changed during engagement')
        ExecutionAssignmentLink(execution_id, assignment_id, ordinal).insert(db)
    for exact_target in routes:
        ResponseObligation(execution_id, exact_target, PendingResponse(), None, now, now, 1).insert(db)
    return Applied(self.snapshots.get(execution_id))

def mark_pending(self, execution_id: str, *, expected_revision: int) -> Applied[RecoverySnapshot]:
    with self.session.transaction() as db:
        snapshot = self.snapshots.get(execution_id)
        if snapshot.execution.revision != expected_revision:
            raise StaleRevision('execution revision changed')
        if not snapshot.execution.lifecycle.queued:
            raise IdentityConflict('only queued executions can become pending')
        ExecutionRecord.update(db, where='execution_id=? AND revision=?', parameters=(execution_id, expected_revision), lifecycle=PendingExecution(), revision=expected_revision + 1, updated_at_ms=self.session.now(snapshot.execution.updated_at_ms))
        return Applied(self.snapshots.get(execution_id))

def fail_unstarted(self, execution_id: str, *, expected_revision: int, reason_code: str) -> Applied[RecoverySnapshot]:
    """Fail queued/pending work; v2 cannot resume a pre-attempt deferral."""
    _bounded_reason(reason_code)
    if not reason_code:
        raise ValueError('unstarted settlement requires a reason')
    with self.session.transaction() as db:
        before = self.snapshots.get(execution_id)
        execution = before.execution
        if execution.revision != expected_revision:
            raise StaleRevision('execution revision changed')
        if not execution.lifecycle.unstarted:
            raise IdentityConflict('unstarted failure requires queued/pending work')
        now = self.session.now(execution.updated_at_ms)
        ExecutionRecord.update(db, where='execution_id=?', parameters=(execution_id,), lifecycle=FailedExecution(), revision=execution.revision + 1, reason_code=reason_code, updated_at_ms=now)
        for obligation in before.obligations:
            ResponseObligation.update(db, where='execution_id=? AND exact_target=?', parameters=(execution_id, obligation.exact_target), lifecycle=FailedResponse(), revision=obligation.revision + 1, reason_code=reason_code, updated_at_ms=self.session.now(obligation.updated_at_ms))
        for assignment in before.assignments:
            WakeAssignment.update(db, where='assignment_id=?', parameters=(assignment.assignment_id,), lifecycle=FailedExecution.assignment_state().build(assignment.lifecycle.mode, assignment.lifecycle.execution_id, assignment.lifecycle.exact_target), revision=assignment.revision + 1, updated_at_ms=self.session.now(assignment.updated_at_ms))
        return Applied(self.snapshots.get(execution_id))

def settle(store):
    self.verify(store, error.context)
    return self.stage.fail_terminal(store, self.participant, self.input_id, self.token_digest, error.context, error.failure)

