@classmethod
def resolve_retained(cls, store: Coordination, bus: MessageBus, boundary, *, owner_lookup: str, owner_thread: str, execution_id: str | None=None) -> tuple[RecoverySnapshot, ...]:
    """Finish only frozen responses whose exact keyed bus rows already exist.

        A live owner and a verified released owner share this one response-row
        resolver; neither path appends a second message or clears a pointer.
        """
    _require_bound_stores(bus, store)
    completed: list[RecoverySnapshot] = []
    wire_root_id = bus.log._private_marker_unlocked().root_id
    with store.session.read():
        execution_ids = tuple(SqlValue.for_annotation(str).read(store.session._connection.execute('SELECT DISTINCT i.execution_id FROM publication_intents i JOIN executions e ON e.execution_id=i.execution_id WHERE e.owner_lookup=? AND NOT EXISTS (SELECT 1 FROM publication_receipts r WHERE r.execution_id=i.execution_id AND r.exact_target=i.exact_target) ORDER BY i.execution_id', (owner_lookup,))))
    for current_id in execution_ids:
        if execution_id is not None and current_id != execution_id:
            continue
        snapshot = store.snapshots.get(current_id)
        if snapshot.execution.owner_thread != owner_thread:
            raise StaleFence('retained response belongs to another owner')
        for frozen in snapshot.publication_intents:
            if ResponseObligation.response_record(snapshot.publication_receipts, frozen.exact_target) is not None:
                continue
            with store.session.transaction() as db:
                snapshot = store.snapshots.get(current_id)
                _require_cohort_assignments(store, bus, snapshot, wire_root_id)
                intent, obligation = snapshot.require_publishing_intent(frozen.exact_target)
                attempt = snapshot.require_current_attempt()
                dispatch = cls.one(db, execution_id=current_id, exact_target=frozen.exact_target)
                if dispatch is None or not dispatch.matches_attempt(wire_root_id, current_id, attempt.owner_generation, attempt.attempt_ordinal, frozen.exact_target):
                    raise PublicationUncertain('no matching durable append dispatch')
                matched, _, _ = bus.log._keyed_receipt_unlocked(intent)
                if matched is None:
                    raise PublicationUncertain('no keyed bus receipt; no resend authorized')
                completed.append(dispatch.complete(store, boundary, snapshot, intent, obligation, matched))
    return tuple(completed)

def complete(self, store: Coordination, boundary, snapshot: RecoverySnapshot, intent: PublicationIntents, obligation: ResponseObligation, matched: Message) -> RecoverySnapshot:
    """Record one exact durable keyed row and finish its original attempt."""
    attempt = snapshot.require_current_attempt()
    if not self.matches_attempt(self.wire_root_id, snapshot.execution.execution_id, attempt.owner_generation, attempt.attempt_ordinal, intent.exact_target):
        raise IdentityConflict('response dispatch belongs to another root or owner')
    now = store.session.now(max(snapshot.execution.updated_at_ms, attempt.updated_at_ms))
    PublicationReceipts(execution_id=intent.execution_id, exact_target=intent.exact_target, seq=matched.seq, message_id=matched.message_id, received_at_ms=now).insert(store.session._connection)
    ResponseObligation.update(store.session._connection, where='execution_id=? AND exact_target=? AND revision=?', parameters=(intent.execution_id, intent.exact_target, obligation.revision), lifecycle=PublishedResponse(matched.message_id, matched.seq), revision=obligation.revision + 1, updated_at_ms=store.session.now(obligation.updated_at_ms))
    store.snapshots.get(intent.execution_id).finish_publications(store.session, boundary)
    return store.snapshots.get(intent.execution_id)

def require_source(self, initial, assignment: WakeAssignment) -> None:
    expected = SelectedResponseRoute(initial.message.message_id, initial.message.target, initial.audience.wire_envelope_digest, initial.audience.digest, initial.decisions_digest, assignment.resolver_version, assignment.policy_version, assignment.recipient_lookup, assignment.recipient)
    if self != expected:
        raise IdentityConflict('response sealed route differs from committed source')

def _assert_response_schema(db: sqlite3.Connection) -> None:
    schema = _response_schema()
    tables = tuple((table.declared_name for table in TypedTable.members_with(ResponseTable)))
    try:
        meta = ResponseSchemaMeta.one(db, singleton=1)
        actual = SQLiteSchemaObject.read(db.execute('SELECT name,sql FROM sqlite_master WHERE sql IS NOT NULL AND tbl_name IN (' + ','.join(('?' for _ in tables)) + ')', tables))
    except (sqlite3.Error, ValueError, TypeError) as error:
        raise PublicationActivationBlocked('private response schema is not installed') from error
    if meta != ResponseSchemaMeta(1, 3, _response_digest(schema)):
        raise PublicationActivationBlocked('private response schema version is unsupported')
    if SQLiteSchemaObject.differences(actual, schema) or SQLiteForeignKeys.read(db.execute('PRAGMA foreign_keys')) != [SQLiteForeignKeys(True)]:
        raise PublicationActivationBlocked('private response schema has drifted')

def install_private_response_schema(store: Coordination) -> None:
    """Install the current response tables on a fresh coordinator only."""
    if type(store) is not Coordination:
        raise TypeError('response schema requires the actual coordinator store')
    with store.session.transaction() as db:
        exists = SQLiteSchemaObject.read(db.execute('SELECT name,sql FROM sqlite_master WHERE name=?', (FieldCodec.encode(ResponseSchemaMeta),)))
        if not exists:
            schema = _response_schema()
            for statement in schema.values():
                db.execute(statement)
            ResponseSchemaMeta(1, 3, _response_digest(schema)).insert(db)
        _assert_response_schema(db)

@property
def recipient_lookup(self) -> str:
