def require_live(self, snapshot: RegistrySnapshot, fence: OwnerFence) -> None:
    self.require_snapshot(snapshot, 'response owner turn stopped or changed before publication')
    if self.thread.name != fence.owner_thread:
        raise StaleFence('response turn belongs to a different fenced owner')
    self.require_active_turn()

def resolve_retained(self, store: Coordination, bus: MessageBus) -> tuple[RecoverySnapshot, ...]:
    """Complete only exact retained replies before this owner starts new work."""
    with store.session.boundary(bus) as boundary:
        self.require_snapshot(boundary.registry, 'response owner changed before retained resolution')
        return PublicationAppendDispatches.resolve_retained(store, bus, boundary, owner_lookup=self.recipient_lookup, owner_thread=self.thread.name)

def _publish_owned(self, bus: MessageBus, fence: OwnerFence, replies: tuple[Message, ...], store: Coordination) -> RecoverySnapshot:
    for reply in replies:
        prepare_fenced_response(store, bus, fence, reply.body, exact_target=reply.target, owner_witness=self)
    published: RecoverySnapshot
    for reply in replies:
        published = publish_fenced_response(store, bus, fence, exact_target=reply.target, owner_witness=self).value
        published.require_published_evidence(reply.target)
    from .comms import Comms
    goals = Comms(bus.log.path.parent).goals
    for assignment in published.assignments:
        goals.consume_reply_wait(self, assignment.source)
    return published

def _require_bound_stores(bus: MessageBus, store: Coordination) -> None:
    if type(bus) is not MessageBus or type(store) is not Coordination:
        raise TypeError('response requires real, explicitly gated bus and coordinator stores')
    if store.session.path.name != 'coordination.sqlite3' or Path(bus.log.path.parent).absolute() != Path(store.session.path.parent).absolute() or bus._registry.store.path.absolute() != (bus.log.path.parent / 'registry.json').absolute():
        raise IdentityConflict('response bus and coordinator have different trusted roots')

def _require_response_writes(bus: MessageBus) -> None:
    if bus.publisher._private_response_writes is not True:
        raise PublicationActivationBlocked('private response publication is disabled')

def _require_cohort_assignments(store: Coordination, bus: MessageBus, snapshot: RecoverySnapshot, wire_root_id: str, *, terminal: bool=False) -> None:
    """Bind selected SQL facts to the ORIGINAL bus origin and exact reply route.

    A DM reply targets the original sender, not the DM's incoming target.
    Caller already holds the bus file lock before the SQL transaction.
    """
    db = store.session._connection
    _assert_response_schema(db)
    assert_cohort_schema(db)
    snapshot.require_wire_responses()
    metadata = bus.log._private_marker_unlocked()
    if metadata.root_id != wire_root_id:
        raise IdentityConflict('cohort bus root changed')
    originals = {initial.message.seq: initial for initial in bus.log.delivery_cohorts_unlocked(wire_root_id, tuple((assignment.wire_seq for assignment in snapshot.assignments)))}
    for assignment in snapshot.assignments:
        initial = originals.get(assignment.wire_seq)
        receipts = SelectedResponseRoute.read(db.execute("SELECT r.message_id,r.exact_target,r.envelope_digest,r.audience_digest,r.decisions_digest,r.resolver_version,r.policy_version,m.recipient_lookup,d.canonical_thread FROM claim_batch_members m JOIN claim_batch_receipts r ON r.wire_root_id=m.wire_root_id AND r.wire_seq=m.wire_seq JOIN cohort_delivery_receipts d ON d.wire_root_id=m.wire_root_id AND d.wire_seq=m.wire_seq AND d.claim_id=m.claim_id AND d.kind='selected' WHERE m.claim_id=? AND m.wire_root_id=? AND r.sealed=1", (assignment.assignment_id, wire_root_id)))
        if initial is None or len(receipts) != 1:
            raise IdentityConflict('response claim lacks original bus/cohort authority')
        selected = {recipient.recipient_lookup for recipient, decision in zip(initial.audience.recipients, initial.decisions, strict=True) if type(decision) is WakeDecision}
        if initial.wire_root_id != wire_root_id or assignment.source != initial.message.reference:
            raise IdentityConflict('response claim conflicts with original bus source')
        receipts[0].require_source(initial, assignment)
        if assignment.recipient_lookup not in selected:
            raise IdentityConflict('response recipient was not selected by the original source')
        engagement = assignment.lifecycle.require_completion() if terminal else assignment.lifecycle.require_engagement()
        if engagement.exact_target != initial.message.exact_reply_target:
            raise IdentityConflict('response claim conflicts with original selected bus route')

def _terminal_replay(store: Coordination, fence: OwnerFence, bus: MessageBus, wire_root_id: str, owner_witness: LiveResponseOwner, exact_target: str) -> AlreadyApplied[RecoverySnapshot] | None:
    """A finished immutable receipt may be re-read, never re-published."""
    snapshot = store.snapshots.get(fence.execution_id)
    if ResponseObligation.response_record(snapshot.publication_receipts, exact_target) is None:
        return None
    if snapshot.execution.owner_lookup != owner_witness.recipient_lookup:
        raise StaleFence('finished response belongs to a different SQL recipient')
    attempt = snapshot.require_attempt()
    if attempt.authority != fence.authority:
        raise StaleFence("finished response is not this owner's original attempt")
    intent, receipt = snapshot.require_published_evidence(exact_target)
    _require_cohort_assignments(store, bus, snapshot, wire_root_id, terminal=snapshot.completed_response())
    matched, _, _ = bus.log._keyed_receipt_unlocked(intent)
    if matched is None or matched.reference != receipt.reference:
        raise PublicationUncertain('published SQL receipt has no exact durable bus row')
    return AlreadyApplied(snapshot)

def publish_fenced_response(store: Coordination, bus: MessageBus, fence: OwnerFence, *, exact_target: str, owner_witness: LiveResponseOwner) -> Applied[RecoverySnapshot] | AlreadyApplied[RecoverySnapshot]:
    """Explicit one-time owner append + Tx2. Never call after an uncertain crash."""
    return _settle_fenced_response(store, bus, fence, allow_append=True, exact_target=exact_target, owner_witness=owner_witness)

def resolve_existing_response(store: Coordination, bus: MessageBus, fence: OwnerFence, *, exact_target: str, owner_witness: LiveResponseOwner) -> Applied[RecoverySnapshot] | AlreadyApplied[RecoverySnapshot]:
    """Read-only bus resolution of Tx1; absence never appends or retries."""
    return _settle_fenced_response(store, bus, fence, allow_append=False, exact_target=exact_target, owner_witness=owner_witness)

