    if not self.path.exists():
        raise ProjectionRebuildRequiredError('candidate index needs explicit initial build')
    prior = self._verified_checkpoint(hint.root_id)
    prior_bytes = prior.byte_offset
    if prior.byte_offset >= hint.through_bytes:
        return CandidateCatchUp(prior.byte_offset, True, False)
    more_source_bytes = not self.maintain(max_rows=max_rows, max_bytes=max_bytes)

try:
    with self.snapshot() as db:
        checkpoint = CandidateCheckpoint.current(db)
        if checkpoint is None or checkpoint.root_id != request.root_id or checkpoint.last_seq < request.required_through_seq:
            raise ProjectionUnavailableError('candidate projection is stale or unrelated')
        with self.log.path.open('rb') as stream:
            stat = os.fstat(stream.fileno())
            checkpoint.require_source(stream, stat, request.root_id)
        data = Candidate.read(db.execute(f'SELECT * FROM "{Candidate.declared_name}" WHERE recipient_lookup=? AND source_seq>? ' + (f'AND audience={sql_literal(MessageAudience.OBSERVER)} ' if request.delivery_only else f'AND audience!={sql_literal(MessageAudience.OBSERVER)} ') + 'ORDER BY source_seq LIMIT ?', (request.recipient_lookup, request.after_seq, request.limit + 1)))
        return CandidatePage(checkpoint.last_seq, tuple(data[:request.limit]), len(data) > request.limit)
except (OSError, sqlite3.DatabaseError, ValueError, TypeError) as error:
    raise ProjectionUnavailableError('candidate projection read unavailable') from error

try:
    return unique_fields(pairs)
except ValueError as error:
    raise DuplicateWireKeyError('Duplicate bus object key.') from error

try:
    assert_optional_awareness_schema(db)
    for assignment in assignments:
        current = OwnerGenerations.one(db, owner_lookup=assignment.recipient_lookup)
        if current is None or current.owner_thread != assignment.recipient:
            raise IdentityConflict('optional claim generation has no current canonical owner')
        AwarenessClaimGenerations(claim_id=assignment.assignment_id, wire_root_id=wire_root_id, wire_seq=wire_seq, recipient_lookup=assignment.recipient_lookup, canonical_thread=assignment.recipient, owner_generation=current.generation).insert(db)
except (sqlite3.Error, SchemaVersionError, IdentityConflict, ValueError, TypeError) as error:
    db.execute('ROLLBACK TO optional_awareness_claims')
    _LOG.warning('Optional generation provenance omitted: %r', error, exc_info=error)
finally:
    db.execute('RELEASE optional_awareness_claims')

with bus.log.certified_read() as source, store.session.transaction() as db:
    marker = source.marker
    if marker.root_id != wire_root_id:
        raise IdentityConflict('cohort admission wire root changed')
    if wire_seq <= marker.admission_after_seq:
        raise IdentityConflict('historical source precedes the current admission floor')
    initial = source.delivery(wire_seq)
    assert_cohort_schema(db)
    receipt = ClaimBatchReceipts.one(db, wire_root_id=wire_root_id, wire_seq=wire_seq)
    if receipt is not None:
        return AlreadyApplied(_receipt_matches(db, initial))
    if WakeAssignment.select(db, where='wire_seq=?', parameters=(wire_seq,)):
        raise IdentityConflict('singleton claim cannot be adopted by a cohort')
    if ClaimBatchReceipts.select(db, where='wire_seq=?', parameters=(wire_seq,)):
        raise IdentityConflict('wire sequence already belongs to another cohort root')
    for recipient in initial.audience.recipients:
        if Participants.one(db, participant_lookup=recipient.recipient_lookup) is None:
            raise IdentityConflict('frozen recipient has no durable participant identity')
    accepted_at = store.session.now()
    expected = _expected_assignments(initial, accepted_at)
    ClaimBatchReceipts(wire_root_id=wire_root_id, wire_seq=wire_seq, message_id=initial.message.message_id, exact_target=initial.message.target, envelope_digest=initial.audience.wire_envelope_digest, audience_digest=initial.audience.digest, decisions_digest=initial.decisions_digest, member_count=len(initial.audience.recipients), claim_count=len(expected), manifest_codec=initial.manifest_codec, resolver_version=initial.resolver_version, policy_version=initial.policy_version, accepted_at_ms=accepted_at).insert(db)
    for ordinal, assignment in enumerate(expected):
        assignment.insert(db)
        ClaimBatchMembers(wire_root_id=wire_root_id, wire_seq=wire_seq, ordinal=ordinal, claim_id=assignment.assignment_id, recipient_lookup=assignment.recipient_lookup).insert(db)
    selected = {assignment.recipient_lookup: assignment.assignment_id for assignment in expected}
    for ordinal, recipient in enumerate(initial.audience.recipients):
        assignment_id = selected.get(recipient.recipient_lookup)
        CohortDeliveryReceipts(wire_root_id=wire_root_id, wire_seq=wire_seq, ordinal=ordinal, recipient_lookup=recipient.recipient_lookup, canonical_thread=recipient.canonical_thread, kind='selected' if assignment_id is not None else 'unmentioned_observer', claim_id=assignment_id).insert(db)
    _record_optional_owner_generations(db, expected, wire_root_id, wire_seq)
    ClaimBatchReceipts.update(db, where='wire_root_id=? AND wire_seq=?', parameters=(wire_root_id, wire_seq), sealed=True)
    return Applied(_receipt_matches(db, initial))

with store.session.read():
    while True:
        selected = sealed_cohort_assignments(store, recipient_lookup, after_seq=cursor, limit=100, state_capability=PendingNotification)
        pending.extend((assignment for assignment in selected if assignment.recipient == owner_name))
        if len(selected) < 100:
            return tuple(pending)
        cursor = selected[-1].wire_seq

if row.assignment.lifecycle.records_conversation_response:
    response = row.assignment.lifecycle.recorded_response(originals[row.assignment.source], replies.get(row.assignment.source, ()), row.assignment.recipient_lookup)
    if response is not None:
        row = replace(row, activity=row.activity.recorded_response(response))

try:
    NativeIdentityCheck(row=row, stage=self, owner=owner.coordinator_identity(self.recipient_lookup)).require_valid()
except ReservationViolationError as error:
    raise StaleFence(f'native dispatch identity changed: {error}') from error

try:
    NativeClaimCheck(captured=captured, current=current).require_valid()
except ReservationViolationError as error:
    raise StaleFence(f'selected claim identity changed before native send: {error}') from error

try:
    NativeReservationCheck(row=reserved, stage=self, owner=owner.coordinator_identity(self.recipient_lookup), token_digest=token_digest).require_valid()
except ReservationViolationError as error:
    raise StaleFence(f'native reservation changed before send: {error}') from error

try:
    NativeBindingCheck(row=binding, stage=self, owner=owner.coordinator_identity(self.recipient_lookup), wire_root_id=wire_root_id, prompt_digest=TextDigest(native_request_digest(prompt))).require_valid()
except ReservationViolationError as error:
    raise IdentityConflict(f'native send differs from its durable prompt binding: {error}') from error

with self.session.transaction() as db:
    assignments = tuple((source.assignment for source in sources))
    return self._create(db, execution_id, origin, owner_lookup, owner_thread, max_attempts, sources, assignments)

with self.session.transaction() as db:
    assignments = tuple((source.assignment for source in sources))
    if assignments != settled:
        raise StaleRevision('original claims changed after proved native settlement')
    return self._create(db, execution_id, origin, owner_lookup, owner_thread, max_attempts, sources, assignments)

if row is not None:
    snapshot = self.snapshots.get(execution_id)
    e = snapshot.execution
    if (e.origin, e.owner_lookup, e.owner_thread, e.max_attempts, tuple(sorted((row.exact_target for row in snapshot.obligations))), tuple((link.assignment_id for link in snapshot.links))) != (origin, owner_lookup, owner_thread, max_attempts, tuple(sorted({source.delivery.message.exact_reply_target for source in sources})), assignment_ids):
        raise IdentityConflict('execution identity conflicts')
    return AlreadyApplied(snapshot)

with self.session.transaction() as db:
    snapshot = self.snapshots.get(execution_id)
    if snapshot.execution.revision != expected_revision:
        raise StaleRevision('execution revision changed')
    if not snapshot.execution.lifecycle.queued:
        raise IdentityConflict('only queued executions can become pending')
    ExecutionRecord.update(db, where='execution_id=? AND revision=?', parameters=(execution_id, expected_revision), lifecycle=PendingExecution(), revision=expected_revision + 1, updated_at_ms=self.session.now(snapshot.execution.updated_at_ms))
    return Applied(self.snapshots.get(execution_id))

with self.session.transaction() as db:
    before = self.snapshots.get(execution_id)
    execution = before.execution
    if execution.revision != expected_revision:
        raise StaleRevision('execution revision changed')
    if not execution.lifecycle.unstarted:
        raise IdentityConflict('unstarted failure requires queued/pending work')
    now = self.session.now(execution.updated_at_ms)
    ExecutionRecord.update(db, where='execution_id=?', parameters=(execution_id,), lifecycle=FailedExecution(), revision=execution.revision + 1, reason_code=reason_code, updated_at_ms=now)
    for obligation in before.obligations:
        ResponseObligation.update(db, where='execution_id=? AND exact_target=?', parameters=(execution_id, obligation.exact_target), lifecycle=FailedResponse(), revision=obligation.revision + 1, reason_code=reason_code, updated_at_ms=self.session.now(obligation.updated_at_ms))
    for assignment in before.assignments:
        WakeAssignment.update(db, where='assignment_id=?', parameters=(assignment.assignment_id,), lifecycle=FailedExecution.assignment_state().build(assignment.lifecycle.mode, assignment.lifecycle.execution_id, assignment.lifecycle.exact_target), revision=assignment.revision + 1, updated_at_ms=self.session.now(assignment.updated_at_ms))
    return Applied(self.snapshots.get(execution_id))

try:
    meta = ResponseSchemaMeta.one(db, singleton=1)
    actual = SQLiteSchemaObject.read(db.execute('SELECT name,sql FROM sqlite_master WHERE sql IS NOT NULL AND tbl_name IN (' + ','.join(('?' for _ in tables)) + ')', tables))
except (sqlite3.Error, ValueError, TypeError) as error:
    raise PublicationActivationBlocked('private response schema is not installed') from error

if not exists:
    schema = _response_schema()
    for statement in schema.values():
        db.execute(statement)
    ResponseSchemaMeta(1, 3, _response_digest(schema)).insert(db)

with store.session.boundary(bus) as boundary:
    self.require_snapshot(boundary.registry, 'response owner changed before retained resolution')
    return PublicationAppendDispatches.resolve_retained(store, bus, boundary, owner_lookup=self.recipient_lookup, owner_thread=self.thread.name)

if existing is not None:
    snapshot.require_existing_preparation(Message(execution.owner_thread, target, payload, message_type, timestamp=existing.message.timestamp if timestamp is None else timestamp, notice=notice, answers=answers))
    return AlreadyApplied(existing)

if prior is None:
    PublicationAppendDispatches(fence.execution_id, exact_target, wire_root_id, fence.owner_generation, fence.attempt_ordinal, store.session.now(snapshot.execution.updated_at_ms)).insert(db)
    first_dispatch = True
elif not prior.matches(wire_root_id, fence, exact_target):
    raise IdentityConflict('response dispatch belongs to another root or owner')

if matched is None:
    if not first_dispatch:
        raise PublicationUncertain('no keyed bus receipt; no resend authorized')
    from .response_conversation import ResponseConversation
    conversation = ResponseConversation.capture(bus, snapshot, obligation)
    matched = bus.publisher._publish_keyed_response_unlocked(intent, conversation=conversation, registry_snapshot=registry_snapshot)

if len(matching) > 1:
    from ..coordination_errors import IdentityConflict
    raise IdentityConflict('Selected source has ambiguous response obligations')

if self != initial or self.resolver_version != RESOLVER_VERSION or self.policy_version != POLICY_VERSION:
    from agent_comms.coordination_errors import IdentityConflict
    raise IdentityConflict('claim acceptance requires initial frozen decision')

if self != progress or self.lifecycle.mode != candidate.lifecycle.mode:
    from agent_comms.coordination_errors import IdentityConflict
    raise IdentityConflict('accepted claim identity conflicts')
